package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;

import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.query.QueryResults;
import org.eclipse.rdf4j.query.algebra.QueryModelNode;
import org.eclipse.rdf4j.query.algebra.TupleExpr;
import org.eclipse.rdf4j.query.algebra.helpers.AbstractQueryModelVisitor;
import org.eclipse.rdf4j.query.explanation.Explanation;
import org.eclipse.rdf4j.query.explanation.TelemetryMetricNames;
import org.eclipse.rdf4j.repository.RepositoryConnection;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.sail.lmdb.config.FrontierEstimatorMode;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.eclipse.rdf4j.sail.lmdb.frontier.FrontierStatisticsAvailability;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * Review reproducer for candidate 9: runtime feedback observed by a query that reads its own UNCOMMITTED changes is
 * published into store-wide learned state stamped with the committed data version, and survives rollback.
 */
class LmdbRolledBackFeedbackReviewReproTest {

	private static final String QUERY = """
			SELECT ?s ?o ?v WHERE {
			  ?s <urn:review:p> ?o .
			  ?s <urn:review:q> ?v
			}
			""";
	private static final String FILTER_QUERY = """
			SELECT ?s ?o WHERE {
			  ?s <urn:review:p> ?o .
			  FILTER(CONTAINS(STR(?o), "uncommitted"))
			}
			""";
	private static final int COMMITTED_SUBJECTS = 10;
	private static final int UNCOMMITTED_SUBJECTS = 500;

	@Test
	void rolledBackRowsMustNotBecomeLearnedOrExactEvidence(@TempDir Path dataDirectory) {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc")
				.setFrontierEstimatorMode(FrontierEstimatorMode.AUTHORITATIVE)
				.setFrontierSynopsisBudgetBytes(32L * 1024L * 1024L);
		LmdbStore store = new LmdbStore(dataDirectory.toFile(), config);
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			try (RepositoryConnection connection = repository.getConnection()) {
				connection.begin();
				addSubjects(connection, "committed", COMMITTED_SUBJECTS);
				connection.commit();
			}
			assertEquals(FrontierStatisticsAvailability.READY, store.rebuildFrontierStatistics().availability());

			// committed baseline: execute twice so any committed-data feedback is learned first
			for (int i = 0; i < 2; i++) {
				try (RepositoryConnection connection = repository.getConnection()) {
					assertEquals(COMMITTED_SUBJECTS,
							QueryResults.asList(connection.prepareTupleQuery(QUERY).evaluate()).size());
				}
			}
			List<String> baseline = plannedJoinEstimates(repository);

			// a transaction reads its own uncommitted rows, then rolls back
			try (RepositoryConnection connection = repository.getConnection()) {
				connection.begin();
				addSubjects(connection, "uncommitted", UNCOMMITTED_SUBJECTS);
				for (int i = 0; i < 3; i++) {
					assertEquals(COMMITTED_SUBJECTS + UNCOMMITTED_SUBJECTS,
							QueryResults.asList(connection.prepareTupleQuery(QUERY).evaluate()).size());
				}
				connection.rollback();
			}
			try (RepositoryConnection connection = repository.getConnection()) {
				assertEquals(COMMITTED_SUBJECTS,
						QueryResults.asList(connection.prepareTupleQuery(QUERY).evaluate()).size(),
						"rollback must restore committed data");
			}
			List<String> afterRollback = plannedJoinEstimates(repository);

			assertFalse(baseline.isEmpty(), "precondition: explain exposes the join estimate");
			assertEquals(baseline, afterRollback,
					"planning on committed data must be unaffected by a rolled-back transaction");
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void rolledBackRowsMustNotBecomeExactFilterFacts(@TempDir Path dataDirectory) {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc")
				.setFrontierEstimatorMode(FrontierEstimatorMode.AUTHORITATIVE)
				.setFrontierSynopsisBudgetBytes(32L * 1024L * 1024L);
		LmdbStore store = new LmdbStore(dataDirectory.toFile(), config);
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			try (RepositoryConnection connection = repository.getConnection()) {
				connection.begin();
				addSubjects(connection, "committed", 200);
				connection.commit();
			}
			assertEquals(FrontierStatisticsAvailability.READY, store.rebuildFrontierStatistics().availability());
			for (int i = 0; i < 2; i++) {
				try (RepositoryConnection connection = repository.getConnection()) {
					assertEquals(0,
							QueryResults.asList(connection.prepareTupleQuery(FILTER_QUERY).evaluate()).size());
				}
			}
			List<String> baseline = plannedEstimates(repository, FILTER_QUERY);
			try (RepositoryConnection connection = repository.getConnection()) {
				connection.begin();
				addSubjects(connection, "uncommitted", UNCOMMITTED_SUBJECTS);
				for (int i = 0; i < 3; i++) {
					assertEquals(UNCOMMITTED_SUBJECTS,
							QueryResults.asList(connection.prepareTupleQuery(FILTER_QUERY).evaluate()).size());
				}
				connection.rollback();
			}
			List<String> afterRollback = plannedEstimates(repository, FILTER_QUERY);
			assertFalse(baseline.isEmpty(), "precondition: explain exposes estimates");
			assertEquals(baseline, afterRollback,
					"filter estimates on committed data must be unaffected by a rolled-back transaction");
		} finally {
			repository.shutDown();
		}
	}

	private static void addSubjects(RepositoryConnection connection, String prefix, int count) {
		ValueFactory values = connection.getValueFactory();
		IRI p = values.createIRI("urn:review:p");
		IRI q = values.createIRI("urn:review:q");
		for (int i = 0; i < count; i++) {
			IRI subject = values.createIRI("urn:review:" + prefix + ":s" + i);
			connection.add(subject, p, values.createIRI("urn:review:" + prefix + ":o" + i));
			connection.add(subject, q, values.createIRI("urn:review:" + prefix + ":v" + i));
		}
	}

	private static List<String> plannedJoinEstimates(SailRepository repository) {
		return plannedEstimates(repository, QUERY);
	}

	private static List<String> plannedEstimates(SailRepository repository, String query) {
		try (RepositoryConnection connection = repository.getConnection()) {
			Explanation explanation = connection.prepareTupleQuery(query).explain(Explanation.Level.Optimized);
			TupleExpr optimized = (TupleExpr) explanation.tupleExpr();
			List<String> estimates = new ArrayList<>();
			optimized.visit(new AbstractQueryModelVisitor<RuntimeException>() {
				@Override
				protected void meetNode(QueryModelNode node) {
					if (node instanceof TupleExpr expr && !(node instanceof org.eclipse.rdf4j.query.algebra.QueryRoot)
							&& !(node instanceof org.eclipse.rdf4j.query.algebra.Projection)) {
						estimates.add(expr.getClass().getSimpleName() + " rows=" + expr.getResultSizeEstimate()
								+ " source=" + expr.getStringMetricPlanned(TelemetryMetricNames.PLANNED_ESTIMATE_SOURCE)
								+ " leo=" + expr.getStringMetricPlanned("optimizer.frontierLeo.output_rows.source")
								+ " guarantee=" + expr.getStringMetricPlanned("plannedFrontierGuarantee"));
					}
					super.meetNode(node);
				}
			});
			System.err.println("[review-f7] estimates: " + estimates);
			return estimates;
		}
	}
}
